Cho đường tròn $(O;5\ \text{cm})$ và dây $AB=8$ cm. Gọi $M$ là trung điểm của $AB$; tia $OM$ cắt đường tròn tại $C$.
\begin{center}
\begin{tikzpicture}[scale=0.6]
\draw (0,0) circle (5);
\coordinate (O) at (0,0); \coordinate (A) at (-4,-3); \coordinate (B) at (4,-3); \coordinate (M) at (0,-3); \coordinate (C) at (0,-5);
\draw (A)--(B); \draw (O)--(C);
\draw (0.4,-3)--(0.4,-2.6)--(0,-2.6);
\draw (A)--(C)--(B);
\node[above] at (O) {$O$}; \node[left] at (A) {$A$}; \node[right] at (B) {$B$}; \node[above right] at (M) {$M$}; \node[below] at (C) {$C$};
\end{tikzpicture}
\end{center}

